from django.db import migrations, models

MODELOS_RETIRADOS = ('qwen-3.8-27b', 'gemma-4-31b', 'zai-glm-4.7')
NUEVO_PROVEEDOR = 'gemini'
NUEVO_MODELO = 'gemini-3.5-flash-lite'
NUEVO_RESPALDO = 'groq'


def migrar_modelo_retirado(apps, schema_editor):
    AIModelSetting = apps.get_model('my_news', 'AIModelSetting')
    AIModelSetting.objects.filter(model_name__in=MODELOS_RETIRADOS).update(
        provider=NUEVO_PROVEEDOR,
        model_name=NUEVO_MODELO,
        fallback_provider=NUEVO_RESPALDO,
    )


def revertir(apps, schema_editor):
    AIModelSetting = apps.get_model('my_news', 'AIModelSetting')
    AIModelSetting.objects.filter(model_name=NUEVO_MODELO).update(model_name=MODELOS_RETIRADOS[0])


